#include "CymbalEngine.h"
namespace cymbalforge {
void CymbalEngine::prepare(double rate, int block) { impact.prepare(rate); juce::dsp::ProcessSpec s{rate, (juce::uint32) block, 2}; reverb.prepare(s); }
void CymbalEngine::strike(float v, float p) { ImpactControls c; c.brightness=parameters.brightness.load(); c.decay=parameters.decay.load(); c.choke=parameters.choke.load(); c.complexity=parameters.complexity.load(); c.shimmer=parameters.shimmer.load(); c.noise=parameters.noise.load(); c.subLevel=parameters.subLevel.load(); c.subTune=parameters.subTune.load(); c.subDecay=parameters.subDecay.load(); c.filterCutoff=parameters.filterCutoff.load(); c.filterMix=parameters.filterMix.load(); c.model=parameters.model.load(); c.modes=parameters.modes.load(); impact.trigger(v,p,c); }
void CymbalEngine::render(juce::AudioBuffer<float>& buffer, int start, int count) { buffer.clear(start,count); auto gain=parameters.gain.load(); for(int i=0;i<count;++i) { auto dry=impact.render(); buffer.setSample(0,start+i,dry[0]*gain); buffer.setSample(1,start+i,dry[1]*gain); } juce::dsp::AudioBlock<float> b(buffer); auto sub=b.getSubBlock((size_t)start,(size_t)count); juce::dsp::ProcessContextReplacing<float> c(sub); juce::dsp::Reverb::Parameters p; p.wetLevel=parameters.reverb.load()*0.35f; p.dryLevel=1.0f; p.roomSize=.55f; reverb.setParameters(p); reverb.process(c); }
}
